import json, re, html
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
refs = json.loads(Path('reference-targets.json').read_text())
out = []

def text(x):
    return html.unescape(re.sub(r'<[^>]*>', '', x or ''))

def p(s):
    return '<p>' + s + '</p>'

def paras(*ss):
    return '\n'.join(p(s) for s in ss)

IS = "Pour les exercices relevant de l'impôt sur les sociétés à la distribution, l'imputation s'effectue sur l'impôt exigible à raison des distributions intervenues au cours de l'exercice auquel le crédit ou sa fraction annuelle se rattache. L'absence de distribution ou d'impôt exigible ne reporte ni la naissance du crédit ni la restitution de l'excédent selon les règles du présent article, y compris les règles de fractionnement auxquelles il renvoie. Le calcul du crédit par exercice ne rend exigible aucun impôt ordinaire sur les bénéfices conservés. Une même fraction de crédit ne peut être imputée ou remboursée plus d'une fois ; les cessions et nantissements légalement autorisés demeurent possibles dans leurs conditions propres."
TRANS = "Ces dispositions s'appliquent à compter de l'entrée en vigueur de la loi portant la présente réforme. Les créances, imputations, restitutions, cessions et nantissements antérieurs conservent leurs effets, sans double emploi ; les contrôles, prescriptions et recours demeurent applicables."
APP_TRANS = "La suppression des conditions d'agrément définitif s'applique aux demandes et agréments en cours à l'entrée en vigueur de la loi portant la présente réforme ainsi qu'aux dépenses engagées à compter de cette date. Elle ne remet pas en cause les reprises légalement nées avant cette entrée en vigueur, leurs restitutions éventuelles, prescriptions et recours. Le respect des conditions de fond du crédit et les pouvoirs de contrôle de l'administration demeurent applicables ; aucune déclaration, attestation ou autorisation ne remplace l'agrément définitif supprimé."
REG = "Le bénéfice du crédit n'est pas subordonné au respect de l'ensemble des obligations légales, fiscales et sociales étrangères aux conditions propres de ce crédit. Les obligations de fond du dispositif, les règles relatives aux aides d'Etat et les sanctions des infractions distinctes demeurent applicables."

def effect(kind, key, description, before, after, unit, population, transition, old, new, burdens="Aucune obligation de remplacement n'est instituée par cette mesure ; les contrôles fiscaux de droit commun restent applicables."):
    return dict(kind=kind, measure_id=key, description=description, before=before, after=after, unit=unit, affected_population=population, conditions_and_transition=transition, replacement_or_new_burdens=burdens, source_quote=old, proposed_quote=new)

def coord(a, old, new):
    return effect('coordination','is-distribution-preservation-credits',
        "Coordination de l'utilisation de l'avantage avec le fait générateur de distribution, sans compter une nouvelle suppression d'impôt.",
        "Imputation rattachée à l'impôt sur les sociétés de l'exercice dans le régime annuel de la source ; montant et assiette du crédit fixés par son article constitutif.",
        "Imputation sur le seul IS exigible ; conservation des créances et de leurs règles de restitution, sans IS annuel sur les bénéfices conservés ni double utilisation.",
        'legal_duty', "Entreprises bénéficiaires de l'article " + a['number'],
        "Exercices relevant du régime de distribution ; droits antérieurs et régimes distincts conservés.", old, new,
        "La liquidation de l'avantage reste nécessaire. Aucun acompte sur les bénéfices conservés ni nouveau dépôt annuel de résultats n'est créé ici.")

def add(i, xml, reason, notes, benefit, classification, assessment, limits, newburdens, effects, removed=None):
    a=sources[i]
    b={k:a[k] for k in ['code_id','source_id','source_sha256','number']}
    b.update(proposed_xml=xml,reason=reason,review_notes=notes,status='rewrite_draft',
        substantive_impact=dict(version=1,classification=classification,assessment=assessment,
            scope_limitations=limits,new_burdens_review=newburdens,effects=effects))
    if a['benefit_check_required'] or benefit:
        b['benefit_review']=benefit
    if removed:
        b.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
    b['reference_checks']=[]
    out.append(b)
    return b

def simple(i, title, facts, notes):
    a=sources[i]
    original=p(text(a['source_xml']).strip())
    xml=original+'\n'+p(IS)+'\n'+p(TRANS)
    add(i,xml,
        "Coordination de fond nécessaire, sans nouvelle baisse de prélèvement : conserver le crédit "+title+" et son régime d'utilisation tout en écartant une lecture qui imposerait annuellement les bénéfices conservés ou suspendrait la restitution faute de distribution. Le renvoi de la source est maintenu intégralement ; aucun nouveau taux n'est institué.",
        notes+" Les articles centraux d'assiette, de liquidation et de paiement de l'IS à la distribution, notamment 209, 219 et 1668, appellent leur coordination propre ; ils ne sont pas réécrits dans ce lot. Les conditions du régime constitutif ne sont pas supprimées par la seule adaptation de l'imputation.",
        facts+" L'avantage reste disponible pour toute situation future répondant à son champ légal et pour les créances antérieures encore utilisables ; aucune période historique n'est convertie en date de promulgation de la réforme. L'absence de distribution ne retarde pas la fraction restituable et aucune même créance ne peut être utilisée deux fois.",
        'coordination_only',
        "La source entière est une règle d'imputation favorable. La proposition en préserve le renvoi et précise son fonctionnement sans IS ordinaire annuel ; aucune taxe, déclaration ou autorisation supplémentaire supprimée n'est revendiquée.",
        "Le calcul, les plafonds, les échéances et les reprises propres au crédit restent ceux de son texte constitutif et de son article d'utilisation ; le solde public de la réforme de l'IS n'est pas établi par cet article.",
        "Aucune charge nouvelle identifiée : les mêmes données de liquidation du crédit sont utilisées ; la clause ajoutée n'impose ni distribution, ni investissement, ni registre ni déclaration de résultats supplémentaire.",
        [coord(a,text(a['source_xml']).strip(),IS)])

simple(0,"des métiers d'art",
    "Le crédit de 244 quater O et la restitution prévue par 199 ter N sont préservés. La source de 244 quater O lue dans le corpus conserve ses taux de 10 % et 15 %, son plafond de 30 000 €, ses catégories de bénéficiaires, ses exclusions de cumul et le cadre de minimis.",
    "199 ter N, lu intégralement, prévoit l'imputation de l'année des dépenses et la restitution de l'excédent. Le calendrier civil du IV et la borne du 31 décembre 2026 du VIII de 244 quater O restent hors de la présente coordination. La note de 2005 sur les dépenses 2006-2007 est historique et ne ferme pas à elle seule le champ du texte constitutif actualisé.")

# 220 Q : suppression des deux circuits d'agrément phonographique, coordonnée à 220 octies.
a=sources[1]
q1=text(a['source_xml']).split("L'excédent de crédit d'impôt constitue")[0].strip()
q2="L'excédent de crédit d'impôt constitue au profit de l'entreprise une créance sur l'Etat d'un montant égal. Cette créance est inaliénable et incessible, sauf dans les conditions prévues par les articles L. 313-23 à L. 313-35 du code monétaire et financier."
q3="Aucun agrément provisoire ou définitif, avis d'un comité d'experts ou certificat comptable spécial n'est exigé pour bénéficier du crédit d'impôt défini à l'article 220 octies. Le respect de ses conditions de fond est apprécié dans le cadre du contrôle fiscal, à partir des pièces ordinaires de l'entreprise."
q4="Le seul défaut d'agrément, de certification spéciale ou de respect du délai de vingt-quatre mois suivant la fixation de l'œuvre ou la production du disque numérique polyvalent musical ne peut entraîner le reversement du crédit. Le crédit indûment obtenu en raison de dépenses ou d'œuvres ne remplissant pas les conditions de fond de l'article 220 octies reste susceptible de reprise selon les procédures fiscales applicables."
q5="La déclaration fiscale sur laquelle l'entreprise demande l'imputation ou la restitution du crédit suffit à sa liquidation. Aucune déclaration spéciale distincte ni copie au Centre national de la musique n'est exigée ; aucune liste nominative destinée à un agrément ni certification par un expert-comptable n'est requise. Les pièces comptables et les preuves nécessaires au contrôle des conditions de fond restent soumises à leurs règles ordinaires."
qx=paras(q1,q2,REG,q4,q3,q5,IS,APP_TRANS,TRANS)
add(1,qx,
    "Réforme de fond : retirer les agréments phonographiques provisoire et définitif, l'avis préalable du comité, le document comptable certifié et les listes destinées à ces agréments, ainsi que la déclaration spéciale et sa copie. Les critères objectifs, coûts éligibles, taux, plafonds et limites européennes de 220 octies permettent un contrôle fiscal sans ces visas redondants. La condition générale de régularité pour des obligations étrangères au crédit est retirée, sans dépénaliser les infractions distinctes. La restitution et la cession de créance sont conservées et coordonnées à l'IS à la distribution.",
    "Coordination réciproque avec le IV de 220 octies rédigé dans ce lot. Annexe III 46 quater-0 YT et 46 quater-0 YU lus intégralement : retirer de YT le dépôt spécial, le rattachement exclusif au relevé de solde annuel et la copie au Centre national de la musique ; conserver dans YU l'ordre d'imputation après les crédits non restituables. Les textes réglementaires culturels organisant les comités et agréments doivent être retirés pour ce champ, sans suppression des conditions européennes du VII de 220 octies. La liquidation annuelle du crédit n'est pas un IS annuel. Les reprises déjà nées restent sous le régime antérieur ; aucun remboursement général d'anciennes reprises n'est décidé.",
    "Le crédit phonographique demeure imputable l'exercice des dépenses et son excédent remboursable, y compris sans distribution ; la créance garde sa cession Dailly autorisée. Les taux de 20 % et 40 %, les assiettes, plafonds et coproductions de 220 octies sont maintenus pour les dépenses futures éligibles. L'absence d'un visa ou d'une certification n'exclut plus l'avantage ; seules les conditions substantielles et européennes continuent à le limiter.",
    'material_reduction',
    "Retrait réel des deux autorisations et de leurs pièces spécifiques, du reversement purement procédural et du double circuit déclaratif. Le montant légal du crédit n'est pas diminué. La coordination de l'IS ne constitue pas une seconde baisse de taxe.",
    "Les pièces comptables ordinaires, les critères d'éligibilité et les contrôles fiscaux subsistent. La compatibilité du régime d'aide modifié et les textes réglementaires extérieurs restent à coordonner ; aucun coût net national n'est chiffré.",
    "Aucune charge nouvelle identifiée : le contrôle utilise la comptabilité déjà nécessaire, la demande fiscale existante suffit et aucun dossier, registre ou déclaration ne remplace les agréments et copies supprimés.",
    [effect('authorization_removed','credit-phonographique-fin-agrement-definitif',"Suppression de l'agrément définitif et de ses pièces propres.","Agrément définitif sous vingt-quatre mois, comité, certification par expert-comptable et listes nominatives conditionnant le maintien du crédit.","Aucun agrément définitif ni pièce spéciale ; reprise seulement si les conditions de fond ne sont pas réunies.",'legal_duty',"Entreprises de production phonographique bénéficiaires de 220 octies.","Dossiers en cours et dépenses nouvelles ; reprises légalement nées avant la réforme réservées.","L'agrément à titre définitif est délivré par le ministre chargé de la culture après avis d'un comité d'experts dont les modalités de fonctionnement sont précisées par décret, sur la base de pièces justificatives, comprenant notamment un document comptable certifié par un expert-comptable indiquant le coût définitif des opérations, les moyens de leur financement et faisant apparaître précisément les dépenses engagées ainsi que la liste nominative définitive du personnel non permanent, des entreprises et industries techniques et des prestataires spécialisés, précisant leur nationalité.",q3),
     effect('obligation_removed','credits-culture-fin-regularite-generale',"Retrait de la condition globale de régularité étrangère à l'éligibilité de la dépense.","Tout manquement légal, fiscal ou social interdit l'agrément, même sans rapport avec le crédit.","L'éligibilité demeure fondée sur les conditions propres du crédit ; les infractions distinctes gardent leurs sanctions.",'legal_duty',"Entreprises sollicitant le crédit phonographique.","Demandes non définitivement liquidées à l'entrée en vigueur et dépenses nouvelles, sans annuler les reprises déjà nées.","L'agrément visé au premier alinéa du IV de l'article 220 octies ne peut être accordé lorsque l'ensemble des obligations légales, fiscales et sociales ne sont pas respectées par l'entreprise souhaitant bénéficier du dispositif.",REG),
     coord(a,q1,IS)],
    ["Suppression des agréments phonographiques et de leur avis obligatoire d'experts, sans procédure d'autorisation ou de déclaration équivalente.","Suppression de la certification comptable et des listes nominatives propres au dossier d'agrément définitif.","Suppression de la condition générale de régularité légale, fiscale et sociale sans rapport avec les critères propres du crédit.","Suppression de la déclaration spéciale distincte et de son envoi en copie au Centre national de la musique, constatés dans l'annexe III.","Suppression du reversement fondé uniquement sur l'absence d'agrément définitif dans les vingt-quatre mois."])

def cultural(i, target, delay, extra_notes='', covid=False):
    a=sources[i]
    raw=text(a['source_xml'])
    first=raw.split("L'excédent de crédit d'impôt constitue")[0].strip()
    second="L'excédent de crédit d'impôt constitue au profit de l'entreprise une créance sur l'Etat d'un montant égal. Cette créance est inaliénable et incessible, sauf dans les conditions prévues aux articles L. 313-23 à L. 313-35 du code monétaire et financier."
    fourth="Le bénéfice et le maintien du crédit d'impôt ne sont subordonnés à aucun agrément définitif. Le seul défaut d'un tel agrément, notamment à l'expiration du délai de trente-six mois suivant l'agrément provisoire, ne donne lieu à aucun reversement. L'agrément provisoire et les conditions de fond prévus à l'article "+target+" demeurent applicables."
    fifth="Si les conditions de fond du crédit ne sont pas respectées, les sommes indûment obtenues sont reprises selon les procédures fiscales applicables. Une décision fondée uniquement sur le défaut d'agrément définitif ne peut justifier cette reprise."
    ss=[first,second,REG,fourth]
    if covid:
        ss.append("Pour les reprises légalement nées avant l'entrée en vigueur de la loi portant la présente réforme et demeurant soumises aux règles antérieures, le délai de trente-six mois à compter de l'agrément provisoire est prolongé de quinze mois pour les spectacles ayant obtenu cet agrément entre le 1er juillet 2019 et le 2 juin 2021. Dans ce cas, l'entreprise reverse le crédit d'impôt obtenu au titre des dépenses exposées avant la période de trente-six mois qui précède la date de délivrance de l'agrément définitif. Cette règle ne rétablit aucune obligation d'agrément définitif pour les situations relevant du quatrième alinéa.")
    ss.append(fifth)
    if i==2:
        ss.append("La déclaration fiscale sur laquelle l'entreprise demande l'imputation ou la restitution du crédit suffit à sa liquidation. Aucune déclaration spéciale distincte ni copie au Centre national de la musique n'est exigée. Les justificatifs de fond restent soumis aux règles ordinaires de contrôle.")
    ss.append("La durée indéterminée d'un contrat de travail unique ne fait pas, à elle seule, obstacle à la prise en compte des salaires et charges sociales des personnels affectés aux opérations éligibles, y compris dans les catégories de personnel non permanent du III de l'article "+target+". Seules les rémunérations correspondant aux fonctions et aux périodes d'affectation éligibles sont retenues, sans double compte d'une même dépense. Cette affectation ne fixe aucun terme à l'emploi et n'autorise aucun nouveau contrat à durée déterminée. Les contrats antérieurs et leurs droits restent régis par leurs dispositions transitoires.")
    ss.extend([IS,APP_TRANS,TRANS])
    # La suppression de la condition de régularité bénéficie aussi aux dossiers en cours.
    ss.append("La suppression de la condition générale de régularité s'applique aux demandes en cours et aux dépenses engagées à compter de cette entrée en vigueur, sans remettre en cause les reprises légalement nées auparavant.")
    old="En cas de non-obtention de l'agrément définitif dans un délai de trente-six mois à compter de l'agrément provisoire, l'entreprise doit reverser le crédit d'impôt dont elle a bénéficié."
    benefits="L'imputation de l'exercice des dépenses, la restitution intégrale de l'excédent et la cession de créance selon les articles L. 313-23 à L. 313-35 sont conservées. Le crédit de "+target+" reste ouvert aux futures opérations dans son champ propre, avec ses taux majorés et ses plafonds ; il n'est pas réservé aux anciens contrats. L'absence d'agrément définitif ou de distribution ne retire plus l'avantage. "
    if covid:
        benefits+="La prolongation favorable de quinze mois pour les agréments du 1er juillet 2019 au 2 juin 2021 est expressément conservée pour les reprises anciennes où elle reste utile ; elle ne limite pas la dispense future d'agrément définitif."
    else:
        benefits+="L'agrément provisoire n'est ni remplacé ni durci par le présent article ; ses conditions de fond et les limites européennes propres au dispositif demeurent."
    removed=["Suppression de l'agrément définitif supplémentaire et du reversement fondé seulement sur son absence au terme des trente-six mois.","Suppression de l'exclusion générale pour manquement à des obligations légales, fiscales ou sociales étrangères aux conditions propres du crédit."]
    if i==2: removed.append("Suppression de la déclaration spéciale distincte et de sa copie obligatoire au Centre national de la musique, prévues par l'annexe III 46 quater-0 YW ter.")
    add(i,paras(*ss),
        "Réforme de fond : retirer le second agrément et la perte du crédit au seul dépassement du délai, ainsi que le filtre général de régularité sans rapport avec l'éligibilité. Le contrôle fiscal des critères substantiels suffit pour les dépenses déjà couvertes par un agrément provisoire ; aucun visa ou dépôt de remplacement n'est créé. L'imputation, la restitution et la créance cessible sont coordonnées à l'IS à la distribution sans modifier les taux ni les dépenses du dispositif constitutif."+(" Le dépôt spécial et sa copie sont également retirés." if i==2 else ''),
        "L'article "+target+" conserve l'agrément provisoire et les conditions de fond de l'aide ; les décrets de délivrance et de fonctionnement des comités doivent être coordonnés pour ne pas rétablir l'agrément définitif. Les obligations européennes de compatibilité et de contrôle des aides restent à examiner avant mise en œuvre ; leur satisfaction n'est pas présumée. "+extra_notes+" Les reprises antérieures légalement nées, leurs restitutions et recours sont protégés ; la suppression future d'une formalité ne vaut pas restitution générale. L'exercice de calcul du crédit n'est pas un fait générateur annuel d'IS.",
        benefits,'material_reduction',
        "Par rapport à la source entière, l'entreprise n'a plus à obtenir un second agrément pour conserver un crédit substantiellement éligible et n'est plus exclue pour une irrégularité sans rapport avec ce crédit. Les assiettes et taux favorables ne diminuent pas ; l'adaptation de l'IS est une coordination de la même mesure générale.",
        "L'agrément provisoire, les critères constitutifs et les contrôles européens et fiscaux subsistent. Les décrets d'agrément restent à coordonner hors de cet objet ; le coût public net de l'élargissement n'est pas mesuré.",
        "Aucune charge nouvelle identifiée : ni nouvelle demande, ni attestation de régularité, ni registre, ni échéance ne remplace les conditions supprimées. Les preuves ordinaires des dépenses et de l'éligibilité restent nécessaires comme dans la source.",
        [effect('authorization_removed','credit-'+('editions-musicales' if i==2 else 'spectacle-musical' if i==4 else 'theatre')+'-fin-agrement-definitif',"Suppression du second agrément et du reversement purement procédural.","Agrément définitif à obtenir sous trente-six mois de l'agrément provisoire, à peine de reversement.","Aucun agrément définitif ; l'agrément provisoire et le contrôle des conditions de fond demeurent.",'legal_duty',"Bénéficiaires du crédit de "+target,"Dossiers en cours et dépenses nouvelles ; reprises légalement nées avant réforme préservées.",old,fourth),
         effect('coordination','credits-culture-fin-regularite-generale',"Même suppression du filtre général de régularité que pour le crédit phonographique, dans le champ propre de ce crédit.","Refus du crédit possible pour tout manquement légal, fiscal ou social étranger au dispositif.","Seules les conditions propres du crédit limitent ce bénéfice ; les sanctions autonomes ne sont pas supprimées.",'legal_duty',"Entreprises bénéficiaires de "+target,"Demandes en cours et dépenses nouvelles ; aucune amnistie générale.",("L'agrément mentionné au VI de l'article "+target+(" du présent code" if i in [4,5] else '')+" ne peut être accordé lorsque l'ensemble des obligations légales, fiscales et sociales ne sont pas respectées par l'entreprise souhaitant bénéficier du dispositif."),REG),coord(a,first,IS)],removed)

cultural(2,'220 septdecies',36,"220 septdecies a été lu intégralement : contrat d'édition du II depuis le 1er janvier 2022 avec préférence d'édition et nouveaux talents, dérogation linguistique des microentreprises, exclusion des cachets de l'effectif, taux 15 %/30 %, plafond de dépenses 300 000 € par contrat et 1 600 000 € de prestations externes par exercice, crédit 500 000 €, coédition proportionnelle et article 53 du règlement 651/2014 demeurent. La durée du contrat d'édition n'est pas celle d'un emploi. La note de source vise les exercices clos à compter du 31 décembre 2022. Annexe III 46 quater-0 YW ter lue intégralement : retirer le dépôt spécial et la copie au Centre national de la musique, sans reconstituer un relevé annuel d'IS sur bénéfice conservé.")

